import{_ as e,o as r,c as o,ae as a}from"./chunks/framework.BX6FPmO9.js";const b=JSON.parse('{"title":"VS Code / Cursor 擴充推薦","description":"","frontmatter":{},"headers":[],"relativePath":"VSCODE.md","filePath":"VSCODE.md"}'),d={name:"VSCODE.md"};function s(n,t,i,c,l,h){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="vs-code-cursor-擴充推薦" tabindex="-1">VS Code / Cursor 擴充推薦 <a class="header-anchor" href="#vs-code-cursor-擴充推薦" aria-label="Permalink to &quot;VS Code / Cursor 擴充推薦&quot;">​</a></h1><p><strong>類型</strong>：reference | <strong>權重</strong>：3</p><p>本專案以 <strong>Remix + React + TypeScript + Git flow</strong> 為前提，偏向「實務穩定、低心智負擔」的擴充清單。<br> Clone 後開啟專案時，VS Code / Cursor 會提示「此工作區有擴充推薦」；可<strong>全部安裝</strong>或依下方分類自行挑選。<br><code>extensions.json</code> 只放「第一層 + 第二層」必裝項，其他建議見本文件。</p><hr><h2 id="第一層-team-baseline-必裝" tabindex="-1">第一層：Team Baseline（必裝） <a class="header-anchor" href="#第一層-team-baseline-必裝" aria-label="Permalink to &quot;第一層：Team Baseline（必裝）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>擴充</th><th>用途</th></tr></thead><tbody><tr><td><strong>ESLint</strong> (<code>dbaeumer.vscode-eslint</code>)</td><td>靜態分析核心。專案中負責避免隱性錯誤（未使用變數、hooks 規則等），非僅風格。前提是專案 ESLint 規則已定義清楚。</td></tr><tr><td><strong>Prettier</strong> (<code>esbenp.prettier-vscode</code>)</td><td>只處理格式，不碰語意。與 ESLint 分工清楚時協作成本最低。</td></tr><tr><td><strong>Tailwind CSS IntelliSense</strong> (<code>bradlc.vscode-tailwindcss</code>)</td><td>class 自動完成與衝突提示。Remix + Tailwind / shadcn 專案中幾乎標配，可減少 class 拼錯。</td></tr><tr><td><strong>Vitest</strong> (<code>vitest.explorer</code>)</td><td>在編輯器內執行、除錯、watch Vitest 測試。專案使用 Vitest 時建議安裝。</td></tr><tr><td><strong>GitLens</strong> (<code>eamodio.gitlens</code>)</td><td>檢視誰改、為何改，理解歷史與 legacy。不建議用它做複雜 rebase。</td></tr></tbody></table><hr><h2 id="第二層-large-scale-collaboration-必加" tabindex="-1">第二層：Large-scale collaboration（必加） <a class="header-anchor" href="#第二層-large-scale-collaboration-必加" aria-label="Permalink to &quot;第二層：Large-scale collaboration（必加）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>擴充</th><th>用途</th></tr></thead><tbody><tr><td><strong>TypeScript Hero</strong> (<code>rbbit.typescript-hero</code>)</td><td>快速追 interface / type 使用點，降低大型專案「影響範圍不確定」的心智負擔。</td></tr><tr><td><strong>Path Intellisense</strong> (<code>christian-kohler.path-intellisense</code>)</td><td>補齊 import 路徑。feature-based / alias 多時可減少路徑寫錯。</td></tr><tr><td><strong>Project Manager</strong> (<code>alefragnani.project-manager</code>)</td><td>多 workspace / 大 repo 的專案切換與管理，適合 POC + main 並行或多服務拆分的場景。</td></tr><tr><td><strong>Auto Close Tag</strong> (<code>formulahendry.auto-close-tag</code>)</td><td>多人頻繁改 JSX 結構時，降低無意義 diff。</td></tr><tr><td><strong>Auto Rename Tag</strong> (<code>formulahendry.auto-rename-tag</code>)</td><td>多人頻繁改 JSX 結構時，降低無意義 diff。</td></tr></tbody></table><hr><h2 id="第三層-framework-aware-協作品質用-視專案" tabindex="-1">第三層：Framework-aware（協作品質用，視專案） <a class="header-anchor" href="#第三層-framework-aware-協作品質用-視專案" aria-label="Permalink to &quot;第三層：Framework-aware（協作品質用，視專案）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>擴充</th><th>用途</th></tr></thead><tbody><tr><td><strong>ES7+ React/Redux Snippets</strong> (<code>dsznajder.es7-react-js-snippets</code>)</td><td>一致的 component / hook 形狀，讓 code review 負擔更低。</td></tr><tr><td><strong>Remix Dev Tools</strong> (<code>remix-run.remix-dev-tools</code>)</td><td>Remix 官方除錯工具，開發期需要時再裝即可。</td></tr></tbody></table><hr><h2 id="第四層-optional-依個人-團隊" tabindex="-1">第四層：Optional（依個人/團隊） <a class="header-anchor" href="#第四層-optional-依個人-團隊" aria-label="Permalink to &quot;第四層：Optional（依個人/團隊）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>擴充</th><th>用途</th></tr></thead><tbody><tr><td><strong>Git Graph</strong> (<code>mhutchie.git-graph</code>)</td><td>視覺化 branch / PR 關係，對多分支策略與新成員有幫助。</td></tr><tr><td><strong>Error Lens</strong> (<code>usernamehw.errorlens</code>)</td><td>錯誤直接顯示在行內。TS 密集時直觀，部分人覺得畫面較滿。</td></tr><tr><td><strong>Todo Tree</strong> (<code>gruntfuggly.todo-tree</code>)</td><td>集中檢視 TODO / FIXME。不適合「嚴禁 TODO 留 codebase」的團隊。</td></tr><tr><td><strong>Cursor</strong> (<code>anysphere.cursor</code>)</td><td>若使用 Cursor 作為編輯器可安裝，其餘可略。</td></tr></tbody></table><hr><h2 id="不需特別安裝" tabindex="-1">不需特別安裝 <a class="header-anchor" href="#不需特別安裝" aria-label="Permalink to &quot;不需特別安裝&quot;">​</a></h2><ul><li><strong>Remix 專用擴充</strong>：除上述 Remix Dev Tools 外，不需再找其他 Remix 專用擴充；Remix 本質是 React + Web APIs，顧好 ESLint / TS / React 工具鏈即可。</li><li><strong>魔法型擴充</strong>：不建議裝會自動改架構、強改 import 的擴充，易與專案既有規範衝突。</li></ul><hr><h2 id="安裝方式" tabindex="-1">安裝方式 <a class="header-anchor" href="#安裝方式" aria-label="Permalink to &quot;安裝方式&quot;">​</a></h2><ol><li>Clone 專案後用 VS Code 或 Cursor 開啟專案資料夾。</li><li>若出現「此工作區有擴充推薦」，點 <strong>「安裝全部」</strong> 或依 <code>docs/VSCODE.md</code> 自行勾選。</li><li>未自動跳出時：<code>Ctrl+Shift+X</code>（擴充）→ 搜尋上述名稱，或由 <strong>指令面板</strong> 執行「Extensions: Show Recommended Extensions」。</li></ol><p>專案內 <code>.vscode/extensions.json</code> 即為推薦清單；<code>.vscode/settings.json</code> 已配合 ESLint、Prettier、Tailwind 與匯入偏好做儲存時格式與檢查。</p>',22)])])}const m=e(d,[["render",s]]);export{b as __pageData,m as default};
